        h.assertTrue(gathering.stream().anyMatch(j->j.kind()==SocietyWork.Kind.PRUNE) && gathering.stream().anyMatch(j->j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA.get())) && gathering.stream().noneMatch(j->j.kind()==SocietyWork.Kind.CRAFT || j.kind()==SocietyWork.Kind.FETCH_BUILD || j.kind()==SocietyWork.Kind.FETCH_PICKAXE || j.kind()==SocietyWork.Kind.HARVEST_FIELD || j.kind()==SocietyWork.Kind.GATHER_FIELD && level.getEntity(j.index()) instanceof net.minecraft.world.entity.item.ItemEntity item && item.getItem().is(ModItems.GUAVA_LOG.get())),"Ready housed parents preserve their reserve through useful food gathering while optional wood, bedding, the eighth quarry stone and inedible wheat wait");
        var patient=ModEntities.BUNNIDOG.get().create(level,net.minecraft.world.entity.EntitySpawnReason.COMMAND);patient.setGenome(Genome.DEFAULT);patient.setStats(Stats.ZERO);patient.setAge(0);patient.setHealth(patient.getMaxHealth());patient.setNoAi(true);patient.society().settle(home);var recovery=home.getBlockPos().west(8);level.setBlock(recovery,ModBlocks.NEST.get().defaultBlockState(),3);level.getPoiManager().add(recovery,ModPoi.NEST);WildFamilyGameTest.at(patient,recovery);level.addFreshEntity(patient);
        h.assertTrue(patient.moveHomeTo(level,recovery)==NestHome.MoveResult.MOVED,"An actual fourth citizen claims its recovery bed");patient.snapTo(net.minecraft.world.phys.Vec3.atBottomCenterOf(recovery.north(5)));var enemy=h.spawnWithNoFreeWill(net.minecraft.world.entity.EntityTypes.HUSK,34,180,25);h.assertTrue(patient.hurtServer(level,level.damageSources().mobAttack(enemy),100) && patient.combat().downed(),"A real lethal mob hit creates an urgent civic rescue need");enemy.discard();var saved=net.minecraft.world.level.storage.TagValueOutput.createWithContext(ProblemReporter.DISCARDING,level.registryAccess());patient.saveWithoutId(saved);var quiet=saved.buildResult();quiet.putInt("CombatDanger",0);patient.load(TagValueInput.create(ProblemReporter.DISCARDING,level.registryAccess(),quiet));
        worker.setStats(Stats.ZERO.with(Stat.BLOOM,10));home.put(new ItemStack(Items.LEATHER));home.put(new ItemStack(Items.LEAD));
